/*
 * Tiny JSON reader for test fixtures (host only, uses malloc). Supports objects, arrays, strings with the common
 * escapes, numbers, true/false/null. Not a general-purpose or hardened parser: fixtures are generated by us.
 */
#ifndef BK_MINI_JSON_H
#define BK_MINI_JSON_H

#include <stddef.h>

typedef enum { JV_NULL, JV_BOOL, JV_NUM, JV_STR, JV_ARR, JV_OBJ } jv_type_t;

typedef struct jv {
    jv_type_t type;
    double num; /* number or bool (0/1) */
    char *str;
    size_t len; /* string length, array length or number of object members */
    struct jv *kids;
    char **keys;
} jv_t;

/* Parses `text`; returns NULL and fills `err` on failure. Free with jv_free(). */
jv_t *jv_parse(const char *text, char *err, size_t err_cap);
void jv_free(jv_t *root);

/* Accessors; they never fail: a missing member / wrong type yields a null node, 0 or "". */
const jv_t *jv_get(const jv_t *obj, const char *key);
const jv_t *jv_at(const jv_t *arr, size_t index);
double jv_num(const jv_t *v);
const char *jv_str(const jv_t *v);

/* Reads a whole file into a NUL-terminated heap buffer; NULL on failure. */
char *jv_read_file(const char *path);

#endif /* BK_MINI_JSON_H */
